-- FUNC05 - Educação e Gestão Escolar. PostgreSQL 16+, idempotente e não destrutiva.
create schema if not exists sigov;
create table if not exists sigov.educacao_escola (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, nome varchar(200) not null, codigo_inep varchar(20), endereco text, telefone varchar(30), email varchar(180), tipo varchar(20) not null default 'OUTRO', status varchar(10) not null default 'ATIVA', capacidade_geral integer not null default 0 check(capacidade_geral>=0));
create table if not exists sigov.educacao_aluno (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, nome varchar(200) not null, data_nascimento date not null, documento varchar(30), sexo varchar(20), endereco text, metadados_protegidos jsonb not null default '{}'::jsonb, status varchar(20) not null default 'ATIVO');
create table if not exists sigov.educacao_responsavel (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, nome varchar(200) not null, documento varchar(30), telefone varchar(30), email varchar(180), parentesco varchar(50), status varchar(10) not null default 'ATIVO');
create table if not exists sigov.educacao_professor (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, nome varchar(200) not null, documento varchar(30), matricula_funcional varchar(50), email varchar(180), telefone varchar(30), escolaridade varchar(100), vinculo varchar(80), carga_horaria numeric(7,2) not null default 0 check(carga_horaria>=0), status varchar(10) not null default 'ATIVO');
create table if not exists sigov.educacao_serie_etapa (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, codigo varchar(30) not null, nome varchar(150) not null, metodologia varchar(10) not null default 'NOTA', ativo boolean not null default true);
create table if not exists sigov.educacao_componente_curricular (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, codigo varchar(30) not null, nome varchar(150) not null, ativo boolean not null default true);
create table if not exists sigov.educacao_aluno_responsavel (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, aluno_id bigint not null references sigov.educacao_aluno(id), responsavel_id bigint not null references sigov.educacao_responsavel(id), responsavel_legal boolean not null default false, autorizado_buscar boolean not null default false);
create table if not exists sigov.educacao_ano_letivo (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, escola_id bigint not null references sigov.educacao_escola(id), ano integer not null check(ano between 2000 and 2200), data_inicio date not null, data_fim date not null, status varchar(12) not null default 'ABERTO', check(data_fim>=data_inicio));
create table if not exists sigov.educacao_periodo_avaliativo (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, ano_letivo_id bigint not null references sigov.educacao_ano_letivo(id), nome varchar(100) not null, data_inicio date not null, data_fim date not null, status varchar(12) not null default 'ABERTO', check(data_fim>=data_inicio));
create table if not exists sigov.educacao_turma (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, escola_id bigint not null references sigov.educacao_escola(id), ano_letivo_id bigint not null references sigov.educacao_ano_letivo(id), serie_etapa_id bigint not null references sigov.educacao_serie_etapa(id), professor_regente_id bigint references sigov.educacao_professor(id), codigo varchar(30) not null, nome varchar(150) not null, turno varchar(10) not null, capacidade integer not null check(capacidade>0), status varchar(12) not null default 'ABERTA');
create table if not exists sigov.educacao_turma_professor (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, turma_id bigint not null references sigov.educacao_turma(id), professor_id bigint not null references sigov.educacao_professor(id), componente_curricular_id bigint not null references sigov.educacao_componente_curricular(id), carga_horaria numeric(7,2) not null check(carga_horaria>0), dia_semana smallint, horario time);
create table if not exists sigov.educacao_matricula (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, aluno_id bigint not null references sigov.educacao_aluno(id), escola_id bigint not null references sigov.educacao_escola(id), ano_letivo_id bigint not null references sigov.educacao_ano_letivo(id), serie_etapa_id bigint not null references sigov.educacao_serie_etapa(id), turma_id bigint references sigov.educacao_turma(id), numero varchar(50) not null, data_matricula date not null default current_date, situacao varchar(15) not null default 'ATIVA', justificativa text);
create table if not exists sigov.educacao_matricula_historico (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, matricula_id bigint not null references sigov.educacao_matricula(id), situacao_anterior varchar(15), situacao_nova varchar(15) not null, turma_anterior_id bigint, turma_nova_id bigint, justificativa text, ocorrido_em timestamptz not null default now());
create table if not exists sigov.educacao_frequencia_aula (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, turma_id bigint not null references sigov.educacao_turma(id), componente_curricular_id bigint not null references sigov.educacao_componente_curricular(id), professor_id bigint not null references sigov.educacao_professor(id), data_aula date not null, conteudo text not null, observacao text);
create table if not exists sigov.educacao_frequencia_aluno (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, frequencia_aula_id bigint not null references sigov.educacao_frequencia_aula(id), aluno_id bigint not null references sigov.educacao_aluno(id), status varchar(12) not null, justificativa text);
create table if not exists sigov.educacao_avaliacao (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, turma_id bigint not null references sigov.educacao_turma(id), componente_curricular_id bigint not null references sigov.educacao_componente_curricular(id), periodo_avaliativo_id bigint not null references sigov.educacao_periodo_avaliativo(id), instrumento varchar(100) not null, data_avaliacao date not null, peso numeric(6,2), nota_maxima numeric(6,2), status varchar(12) not null default 'ABERTA');
create table if not exists sigov.educacao_nota_aluno (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, avaliacao_id bigint not null references sigov.educacao_avaliacao(id), aluno_id bigint not null references sigov.educacao_aluno(id), nota numeric(6,2), conceito varchar(30), parecer text, recuperacao boolean not null default false);
create table if not exists sigov.educacao_ocorrencia (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, aluno_id bigint not null references sigov.educacao_aluno(id), escola_id bigint not null references sigov.educacao_escola(id), turma_id bigint references sigov.educacao_turma(id), tipo varchar(12) not null, ocorrido_em timestamptz not null, descricao_protegida text not null, providencia_protegida text, registrado_por bigint not null);
create table if not exists sigov.educacao_prematricula (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, protocolo varchar(50) not null, aluno_id bigint references sigov.educacao_aluno(id), nome_interessado varchar(200) not null, responsavel_id bigint references sigov.educacao_responsavel(id), escola_id bigint not null references sigov.educacao_escola(id), serie_etapa_id bigint not null references sigov.educacao_serie_etapa(id), turno varchar(10), endereco text, status varchar(15) not null default 'RECEBIDA', justificativa text);
create table if not exists sigov.educacao_comunicado (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, escola_id bigint not null references sigov.educacao_escola(id), turma_id bigint references sigov.educacao_turma(id), titulo varchar(180) not null, mensagem text not null, publicado_em timestamptz not null default now(), ativo boolean not null default true);
create table if not exists sigov.educacao_portal_vinculo (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, usuario_id bigint not null, aluno_id bigint not null references sigov.educacao_aluno(id), responsavel_id bigint references sigov.educacao_responsavel(id), status varchar(10) not null default 'ATIVO');
create table if not exists sigov.educacao_auditoria (id bigint generated always as identity primary key, tenant_id bigint not null, entidade_id bigint not null, created_at timestamptz not null default now(), updated_at timestamptz, created_by bigint, updated_by bigint, is_deleted boolean not null default false, tabela varchar(100) not null, registro_id bigint not null, operacao varchar(30) not null, antes jsonb, depois jsonb, usuario_id bigint, ocorrido_em timestamptz not null default now(), correlation_id varchar(100));
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_escola_tipo') then alter table sigov.educacao_escola add constraint educacao_escola_tipo check (tipo in ('INFANTIL','FUNDAMENTAL','EJA','OUTRO')); end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_escola_status') then alter table sigov.educacao_escola add constraint educacao_escola_status check (status in ('ATIVA','INATIVA')); end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_aluno_status') then alter table sigov.educacao_aluno add constraint educacao_aluno_status check (status in ('ATIVO','TRANSFERIDO','EVADIDO','CONCLUINTE','INATIVO')); end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_professor_status') then alter table sigov.educacao_professor add constraint educacao_professor_status check (status in ('ATIVO','AFASTADO','INATIVO')); end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_metodologia') then alter table sigov.educacao_serie_etapa add constraint educacao_metodologia check (metodologia in ('NOTA','CONCEITO','PARECER')); end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_ano_status') then alter table sigov.educacao_ano_letivo add constraint educacao_ano_status check (status in ('PLANEJADO','ABERTO','ENCERRADO')); end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_periodo_status') then alter table sigov.educacao_periodo_avaliativo add constraint educacao_periodo_status check (status in ('ABERTO','ENCERRADO')); end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_turma_turno') then alter table sigov.educacao_turma add constraint educacao_turma_turno check (turno in ('MANHA','TARDE','NOITE','INTEGRAL')); end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_turma_status') then alter table sigov.educacao_turma add constraint educacao_turma_status check (status in ('ABERTA','FECHADA','ENCERRADA')); end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_matricula_situacao') then alter table sigov.educacao_matricula add constraint educacao_matricula_situacao check (situacao in ('ATIVA','PRE_MATRICULA','TRANSFERIDA','CANCELADA','ABANDONO','CONCLUIDA')); end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_frequencia_status') then alter table sigov.educacao_frequencia_aluno add constraint educacao_frequencia_status check (status in ('PRESENTE','FALTA','JUSTIFICADA')); end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_ocorrencia_tipo') then alter table sigov.educacao_ocorrencia add constraint educacao_ocorrencia_tipo check (tipo in ('DISCIPLINAR','PEDAGOGICA','SAUDE','OUTRA')); end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='educacao_prematricula_status') then alter table sigov.educacao_prematricula add constraint educacao_prematricula_status check (status in ('RECEBIDA','EM_ANALISE','DEFERIDA','INDEFERIDA','LISTA_ESPERA','CANCELADA')); end if; end $$;
create unique index if not exists ux_educacao_escola_inep on sigov.educacao_escola(tenant_id,entidade_id,codigo_inep) where codigo_inep is not null and not is_deleted;
create unique index if not exists ux_educacao_aluno_documento on sigov.educacao_aluno(tenant_id,entidade_id,documento) where documento is not null and not is_deleted;
create unique index if not exists ux_educacao_responsavel_documento on sigov.educacao_responsavel(tenant_id,entidade_id,documento) where documento is not null and not is_deleted;
create unique index if not exists ux_educacao_professor_documento on sigov.educacao_professor(tenant_id,entidade_id,documento) where documento is not null and not is_deleted;
create unique index if not exists ux_educacao_professor_matricula on sigov.educacao_professor(tenant_id,entidade_id,matricula_funcional) where matricula_funcional is not null and not is_deleted;
create unique index if not exists ux_educacao_matricula_ativa on sigov.educacao_matricula(tenant_id,entidade_id,aluno_id,escola_id,ano_letivo_id,serie_etapa_id) where situacao='ATIVA' and not is_deleted;
