create index if not exists ix_educacao_turma_professor_escopo on sigov.educacao_turma_professor(tenant_id,entidade_id,turma_id,professor_id);
create index if not exists ix_educacao_matricula_escopo on sigov.educacao_matricula(tenant_id,entidade_id,escola_id,ano_letivo_id,turma_id,aluno_id);
