create or replace function sigov.fn_educacao_validar_operacao() returns trigger language plpgsql as $$
declare v_status text; v_cap integer; v_ocupadas bigint; v_metodo text; v_ano_status text; v_max numeric;
begin
 if tg_table_name='educacao_turma' then select status into v_status from sigov.educacao_escola where id=new.escola_id and not is_deleted; if v_status<>'ATIVA' then raise exception 'Escola inativa não recebe turma'; end if; end if;
 if tg_table_name='educacao_matricula' and new.situacao='ATIVA' then
  select e.status,t.status,t.capacidade into v_status,v_metodo,v_cap from sigov.educacao_escola e left join sigov.educacao_turma t on t.id=new.turma_id where e.id=new.escola_id;
  if v_status<>'ATIVA' then raise exception 'Escola inativa não recebe matrícula'; end if;
  if new.turma_id is not null then select count(*) into v_ocupadas from sigov.educacao_matricula where turma_id=new.turma_id and situacao='ATIVA' and not is_deleted and id<>coalesce(new.id,0); if v_metodo<>'ABERTA' or v_ocupadas>=v_cap then raise exception 'Turma encerrada ou sem vaga'; end if; end if;
 end if;
 if tg_table_name='educacao_nota_aluno' then select a.nota_maxima,p.status,al.status,se.metodologia into v_max,v_status,v_ano_status,v_metodo from sigov.educacao_avaliacao a join sigov.educacao_periodo_avaliativo p on p.id=a.periodo_avaliativo_id join sigov.educacao_turma t on t.id=a.turma_id join sigov.educacao_ano_letivo al on al.id=t.ano_letivo_id join sigov.educacao_serie_etapa se on se.id=t.serie_etapa_id where a.id=new.avaliacao_id; if v_status='ENCERRADO' or v_ano_status='ENCERRADO' then raise exception 'Período ou ano encerrado'; end if; if new.nota is not null and (new.nota<0 or new.nota>v_max) then raise exception 'Nota fora do intervalo'; end if; end if;
 return new;
end $$;
drop trigger if exists trg_educacao_validar_turma on sigov.educacao_turma; create trigger trg_educacao_validar_turma before insert or update on sigov.educacao_turma for each row execute function sigov.fn_educacao_validar_operacao();
drop trigger if exists trg_educacao_validar_matricula on sigov.educacao_matricula; create trigger trg_educacao_validar_matricula before insert or update on sigov.educacao_matricula for each row execute function sigov.fn_educacao_validar_operacao();
drop trigger if exists trg_educacao_validar_nota on sigov.educacao_nota_aluno; create trigger trg_educacao_validar_nota before insert or update on sigov.educacao_nota_aluno for each row execute function sigov.fn_educacao_validar_operacao();
