('educacao.professor.criar','educacao.professor','criar','Permissão FUNC05'),
('educacao.professor.editar','educacao.professor','editar','Permissão FUNC05'),
('educacao.anoletivo.gerenciar','educacao.anoletivo','gerenciar','Permissão FUNC05'),
('educacao.turma.visualizar','educacao.turma','visualizar','Permissão FUNC05'),
('educacao.turma.criar','educacao.turma','criar','Permissão FUNC05'),
('educacao.turma.editar','educacao.turma','editar','Permissão FUNC05'),
('educacao.matricula.visualizar','educacao.matricula','visualizar','Permissão FUNC05'),
('educacao.matricula.criar','educacao.matricula','criar','Permissão FUNC05'),
('educacao.matricula.transferir','educacao.matricula','transferir','Permissão FUNC05'),
('educacao.frequencia.visualizar','educacao.frequencia','visualizar','Permissão FUNC05'),
('educacao.frequencia.lancar','educacao.frequencia','lancar','Permissão FUNC05'),
('educacao.avaliacao.visualizar','educacao.avaliacao','visualizar','Permissão FUNC05'),
('educacao.avaliacao.lancar','educacao.avaliacao','lancar','Permissão FUNC05'),
('educacao.ocorrencia.visualizar','educacao.ocorrencia','visualizar','Permissão FUNC05'),
